/**
 * Makes `performance.timeOrigin` the wall-clock time `performance.now()` counts
 * from. A restore sets the wall clock from the host but not the clock behind
 * `performance.now()`, so otherwise `timeOrigin + performance.now()` lags the
 * wall clock by as long as the snapshot was stored. Code that already read
 * `timeOrigin` keeps the old value.
 */
export declare const anchorTimeOriginToRestore: () => void;
